import Database from "better-sqlite3";
import path from "path";

const DB_PATH = "/home/user/qwik-app/chat.db";

let db: Database.Database | null = null;

export interface Message {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.exec(`
      CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user TEXT NOT NULL,
        text TEXT NOT NULL,
        timestamp TEXT NOT NULL
      )
    `);
  }
  return db;
}

export function getAllMessages(): Message[] {
  const database = getDb();
  return database.prepare("SELECT * FROM messages ORDER BY id ASC").all() as Message[];
}

export function insertMessage(user: string, text: string): Message {
  const database = getDb();
  const timestamp = new Date().toISOString();
  const stmt = database.prepare(
    "INSERT INTO messages (user, text, timestamp) VALUES (?, ?, ?)"
  );
  const result = stmt.run(user, text, timestamp);
  return {
    id: result.lastInsertRowid as number,
    user,
    text,
    timestamp,
  };
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getAllMessages, insertMessage, type Message } from "../../../lib/db";

// Store active SSE connections
const clients: Set<ReadableStreamDefaultController> = new Set();

function broadcast(message: Message) {
  const data = `data: ${JSON.stringify(message)}\n\n`;
  const encoder = new TextEncoder();
  const encoded = encoder.encode(data);

  for (const controller of clients) {
    try {
      controller.enqueue(encoded);
    } catch {
      clients.delete(controller);
    }
  }
}

export const onGet: RequestHandler = async ({ send, request }) => {
  const stream = new ReadableStream({
    start(controller) {
      clients.add(controller);

      // Send all existing messages upon connection
      const messages = getAllMessages();
      const encoder = new TextEncoder();
      for (const msg of messages) {
        const data = `data: ${JSON.stringify(msg)}\n\n`;
        try {
          controller.enqueue(encoder.encode(data));
        } catch {
          clients.delete(controller);
          return;
        }
      }
    },
    cancel(controller) {
      clients.delete(controller);
    },
  });

  send(
    new Response(stream, {
      status: 200,
      headers: {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache",
        Connection: "keep-alive",
      },
    })
  );
};

export const onPost: RequestHandler = async ({ request, json }) => {
  let body: { user?: string; text?: string };

  try {
    body = await request.json();
  } catch {
    json(400, { error: "Invalid JSON" });
    return;
  }

  const { user, text } = body;

  if (
    !user ||
    !text ||
    typeof user !== "string" ||
    typeof text !== "string" ||
    user.trim() === "" ||
    text.trim() === ""
  ) {
    json(400, { error: "user and text are required and must be non-empty strings" });
    return;
  }

  const message = insertMessage(user.trim(), text.trim());
  broadcast(message);

  json(201, message);
};

import { component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

interface Message {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

export default component$(() => {
  const messages = useSignal<Message[]>([]);
  const userInput = useSignal("");
  const textInput = useSignal("");
  const error = useSignal("");

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    const eventSource = new EventSource("/api/messages");

    eventSource.onmessage = (event) => {
      try {
        const msg: Message = JSON.parse(event.data);
        messages.value = [...messages.value, msg];
      } catch {
        // ignore malformed messages
      }
    };

    eventSource.onerror = () => {
      // SSE connection error - browser will auto-reconnect
    };

    return () => {
      eventSource.close();
    };
  });

  const handleSubmit = $(async () => {
    const user = userInput.value.trim();
    const text = textInput.value.trim();

    if (!user || !text) {
      error.value = "Both user and text are required.";
      return;
    }

    error.value = "";

    try {
      const res = await fetch("/api/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user, text }),
      });

      if (!res.ok) {
        error.value = "Failed to send message.";
        return;
      }

      // Clear inputs on success
      userInput.value = "";
      textInput.value = "";
    } catch {
      error.value = "Network error. Please try again.";
    }
  });

  return (
    <div>
      <h1>Chat Room</h1>

      <div>
        <input
          id="user-input"
          data-testid="user-input"
          type="text"
          placeholder="Your name"
          value={userInput.value}
          onInput$={(e) => {
            userInput.value = (e.target as HTMLInputElement).value;
          }}
        />
        <input
          id="text-input"
          data-testid="text-input"
          type="text"
          placeholder="Type a message..."
          value={textInput.value}
          onInput$={(e) => {
            textInput.value = (e.target as HTMLInputElement).value;
          }}
          onKeyDown$={(e) => {
            if (e.key === "Enter") {
              handleSubmit();
            }
          }}
        />
        <button
          id="send-button"
          data-testid="send-button"
          onClick$={handleSubmit}
        >
          Send
        </button>
      </div>

      {error.value && (
        <div style={{ color: "red", margin: "8px 0" }}>{error.value}</div>
      )}

      <div id="message-list" data-testid="message-list">
        {messages.value.map((msg) => (
          <div key={msg.id} class="message-item" data-testid="message-item">
            <strong>{msg.user}</strong>: {msg.text}
            <span style={{ color: "#999", fontSize: "0.8em", marginLeft: "8px" }}>
              {new Date(msg.timestamp).toLocaleTimeString()}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "Chat Room",
};

